export type WorkerTaskClaimTransport = Omit<WorkerTransport, "accessToken"> & {
  developerAccessToken?: WorkerTransport["accessToken"];
  workerDeviceToken?: WorkerTransport["accessToken"];
  workerRunToken?: WorkerTransport["accessToken"];
};

export function createWorkerTaskClaimsClient(transport: WorkerTaskClaimTransport) {
  const developerAccessToken = createWorkerRequest({ ...transport, accessToken: async () => {
    if (!transport.developerAccessToken) throw new TypeError("Missing worker credential for this operation");
    return transport.developerAccessToken();
  } }, "cli_at_", "the bound credential for this operation");
  const workerDeviceToken = createWorkerRequest({ ...transport, accessToken: async () => {
    if (!transport.workerDeviceToken) throw new TypeError("Missing worker credential for this operation");
    return transport.workerDeviceToken();
  } }, "wdev_at_", "the bound credential for this operation");
  const workerRunToken = createWorkerRequest({ ...transport, accessToken: async () => {
    if (!transport.workerRunToken) throw new TypeError("Missing worker credential for this operation");
    return transport.workerRunToken();
  } }, "wrun_at_", "the bound credential for this operation");
  return {
    claimWorkerTask(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; body: WorkerTaskClaimInputV1 }, signal?: AbortSignal) {
      return workerDeviceToken("POST", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/task-claims/claim`, signal, { body: input.body, maxBytes: 16384 });
    },
    readWorkerTaskClaimReceipt(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; body: WorkerTaskClaimInputV1 }, signal?: AbortSignal) {
      return workerDeviceToken("POST", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/task-claims/claim-receipt`, signal, { body: input.body, maxBytes: 16384 });
    },
    renewWorkerTask(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; body: WorkerTaskRenewInputV1 }, signal?: AbortSignal) {
      return workerDeviceToken("POST", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/task-claims/renew`, signal, { body: input.body, maxBytes: 16384 });
    },
    readWorkerTaskRenewReceipt(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; body: WorkerTaskRenewInputV1 }, signal?: AbortSignal) {
      return workerDeviceToken("POST", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/task-claims/renew-receipt`, signal, { body: input.body, maxBytes: 16384 });
    },
    releaseWorkerTask(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; body: WorkerTaskReleaseInputV1 }, signal?: AbortSignal) {
      return workerRunToken("POST", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/task-claims/release`, signal, { body: input.body, maxBytes: 16384 });
    },
    readWorkerTaskReleaseReceipt(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; body: WorkerTaskReleaseInputV1 }, signal?: AbortSignal) {
      return workerDeviceToken("POST", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/task-claims/release-receipt`, signal, { body: input.body, maxBytes: 16384 });
    },
    finalizeWorkerTask(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; body: WorkerTaskFinalizeInputV1 }, signal?: AbortSignal) {
      return workerRunToken("POST", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/task-claims/finalize`, signal, { body: input.body, maxBytes: 16384 });
    },
    readWorkerTaskFinalizeReceipt(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; body: WorkerTaskFinalizeInputV1 }, signal?: AbortSignal) {
      return workerDeviceToken("POST", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/task-claims/finalize-receipt`, signal, { body: input.body, maxBytes: 16384 });
    },
    recoverWorkerTask(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; body: WorkerTaskRecoverInputV1 }, signal?: AbortSignal) {
      return developerAccessToken("POST", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/task-claims/recover`, signal, { body: input.body, maxBytes: 16384 });
    },
    readWorkerTaskRecoverReceipt(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; body: WorkerTaskRecoverInputV1 }, signal?: AbortSignal) {
      return developerAccessToken("POST", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/task-claims/recover-receipt`, signal, { body: input.body, maxBytes: 16384 });
    },
    reconcileWorkerTask(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; body: WorkerTaskReconcileInputV1 }, signal?: AbortSignal) {
      return developerAccessToken("POST", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/task-claims/reconcile`, signal, { body: input.body, maxBytes: 16384 });
    },
    readWorkerTaskReconcileReceipt(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; body: WorkerTaskReconcileInputV1 }, signal?: AbortSignal) {
      return developerAccessToken("POST", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/task-claims/reconcile-receipt`, signal, { body: input.body, maxBytes: 16384 });
    },
    issueWorkerTaskRunCredential(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; body: WorkerTaskRunCredentialInputV1 }, signal?: AbortSignal) {
      return workerDeviceToken("POST", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/task-claims/run-credential`, signal, { body: input.body, maxBytes: 16384 });
    },
    readWorkerTaskRunCredential(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; body: WorkerTaskRunSubjectV1 }, signal?: AbortSignal) {
      return workerDeviceToken("POST", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/task-claims/run-credential-receipt`, signal, { body: input.body, maxBytes: 16384 });
    },
    recordWorkerTaskEvidence(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; body: WorkerTaskEvidenceInputV1 }, signal?: AbortSignal) {
      return workerRunToken("POST", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/task-claims/evidence`, signal, { body: input.body, maxBytes: 16384 });
    },
    readWorkerTaskEvidenceReceipt(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; body: WorkerTaskEvidenceInputV1 }, signal?: AbortSignal) {
      return workerDeviceToken("POST", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/task-claims/evidence-receipt`, signal, { body: input.body, maxBytes: 16384 });
    },
    listCLIWorkerReadyDelegations(input: { workspace_id: string; owner_id: string; device_id: string; worker_id: string; epoch: string; connection_intent: string; limit?: number; cursor?: string }, signal?: AbortSignal) {
      if (input.limit !== undefined && (!Number.isInteger(input.limit) ||
          input.limit < 1 || input.limit > 100)) throw new RangeError("Invalid worker limit");
      const query = new URLSearchParams();
      if (input.epoch !== undefined) query.set("epoch", String(input.epoch));
      if (input.connection_intent !== undefined) query.set("connection_intent", String(input.connection_intent));
      if (input.limit !== undefined) query.set("limit", String(input.limit));
      if (input.cursor !== undefined) query.set("cursor", String(input.cursor));
      return workerDeviceToken("GET", `/api/v1/cli/worker-devices/${pathSegment(input.workspace_id)}/${pathSegment(input.owner_id)}/${pathSegment(input.device_id)}/${pathSegment(input.worker_id)}/ready-delegations`, signal, { query });
    },
  };
}

function pathSegment(value: string): string {
  if (!/^[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(value)) throw new TypeError("Invalid worker identifier");
  return value;
}
